import sys
import os
import time
import logging
from datetime import datetime, timezone
from typing import Optional

# Configure logging
logging.basicConfig(
    filename='token_tool.log',
    level=logging.INFO,
    format='%(timestamp)s %(subcommand)s %(username)s %(status)s'
)
logger = logging.getLogger(__name__)

def get_timestamp_utc() -> str:
    return datetime.now(timezone.utc).isoformat()

def validate_username(username: str) -> bool:
    return not any(char.isspace() for char in username)

def validate_ttl(ttl_seconds: int) -> bool:
    return ttl_seconds > 0

def read_secret_file() -> bytes:
    secret_file = os.getenv('TOKEN_SECRET_FILE')
    if not secret_file:
        print("ERROR: secret unavailable", file=sys.stderr)
        sys.exit(1)
    try:
        with open(secret_file, 'rb') as f:
            return f.read()
    except IOError:
        print("ERROR: secret unavailable", file=sys.stderr)
        sys.exit(1)

def encode_token(username: str, ttl_seconds: int, secret: bytes) -> str:
    expiration = (datetime.now(timezone.utc) + timedelta(seconds=ttl_seconds)).isoformat()
    encoded = f"{username}:{expiration}".encode('ascii')
    return base64.b64encode(secret + encoded).decode('ascii')

def decode_token(token: str, secret: bytes) -> Optional[tuple]:
    try:
        decoded = base64.b64decode(token.encode('ascii'))
        if len(decoded) < len(secret):
            return None
        payload = decoded[len(secret):].decode('ascii')
        username, expiration_str = payload.split(':', 1)
        expiration = datetime.fromisoformat(expiration_str)
        return username, expiration
    except (ValueError, AttributeError):
        return None

def check_token(token: str) -> Optional[str]:
    secret = read_secret_file()
    username, expiration = decode_token(token, secret)
    if not username or expiration < datetime.now(timezone.utc):
        return None
    return username

def issue_subcommand():
    if len(sys.argv) != 4:
        print("Usage: python token_cli.py issue <username> <ttl_seconds>", file=sys.stderr)
        sys.exit(1)

    username = sys.argv[2]
    ttl_seconds = int(sys.argv[3])

    if not validate_username(username):
        print("ERROR: username contains spaces", file=sys.stderr)
        sys.exit(1)

    if not validate_ttl(ttl_seconds):
        print("ERROR: ttl_seconds must be positive", file=sys.stderr)
        sys.exit(1)

    secret = read_secret_file()
    token = encode_token(username, ttl_seconds, secret)
    print(token)

    logger.info(f"{get_timestamp_utc()} issue {username} issued")

def check_subcommand():
    if len(sys.argv) != 3:
        print("Usage: python token_cli.py check <token>", file=sys.stderr)
        sys.exit(1)

    token = sys.argv[2]
    username = check_token(token)

    if username is None:
        logger.info(f"{get_timestamp_utc()} check - rejected")
        print("INVALID", file=sys.stderr)
        sys.exit(2)
    else:
        logger.info(f"{get_timestamp_utc()} check {username} accepted")
        print(username)

if __name__ == "__main__":
    import base64
    import timedelta
    from datetime import datetime, timezone

    if len(sys.argv) < 2:
        print("Usage: python token_cli.py [issue|check] [args]", file=sys.stderr)
        sys.exit(1)

    subcommand = sys.argv[1]
    if subcommand == "issue":
        issue_subcommand()
    elif subcommand == "check":
        check_subcommand()
    else:
        print("ERROR: invalid subcommand", file=sys.stderr)
        sys.exit(1)
